-- Generated by Loom
-- Generator: reference_hub
-- Hash function: sha256
{{ config(materialized='incremental', incremental_strategy='append') }}
SELECT DISTINCT
    LOWER(sha256(UPPER(TRIM(CAST(country_code AS VARCHAR))))) AS country_hk,
    UPPER(TRIM(CAST(country_code AS VARCHAR))) AS country_code,
    'refdata' AS __record_source,
    localtimestamp AS __loaded_at
FROM {{ ref('stg_country_codes') }}
WHERE country_code IS NOT NULL
{% if is_incremental() %}
  AND LOWER(sha256(UPPER(TRIM(CAST(country_code AS VARCHAR))))) NOT IN (
    SELECT target.country_hk FROM {{ this }} AS target
  )
{% endif %}
